// Del receptor llega la FILA ENTERA del outbox: { event, payload }. Leer
// `$json` directamente deja todos los numeros en undefined y el correo sale
// con el asunto generico y el cuerpo vacio — que es peor que no mandarlo,
// porque parece que el sistema funciona.
const e = $json.payload || $json;
const h = e.huecos || {};
const partes = [];
if (h.horas > 0 && h.a_quien_ofrecer > 0) partes.push(h.horas + (h.horas === 1 ? ' hora libre' : ' horas libres'));
if (e.plantones > 0) partes.push(e.plantones + (e.plantones === 1 ? ' que no volvió' : ' que no volvieron'));
if (e.propuestas > 0) partes.push(e.propuestas + (e.propuestas === 1 ? ' propuesta sin respuesta' : ' propuestas sin respuesta'));

// El asunto lleva los números. Un asunto genérico se archiva sin abrir, y
// entonces da igual lo bueno que sea el cuerpo.
const asunto = partes.length
  ? 'ToqueFlow · ' + partes.join(' · ')
  : 'ToqueFlow · hay algo por recuperar';

const cuerpo = [
  'Hola,',
  '',
  'Esto es lo que hoy se puede recuperar en ' + (e.empresa || 'tu negocio') + ':',
  '',
  (e.resumen || '').split('\n').map(l => '  · ' + l).join('\n'),
  '',
  'Cada una tiene su botón en el portal, con el mensaje ya redactado:',
  e.enlace || 'https://toqueflow.com/agenda.html',
  '',
  'Nada sale hasta que tú le des a enviar.',
  '',
  '—',
  'Este aviso solo llega cuando hay algo que hacer y cambió desde la última vez.',
].join('\n');

const para = (e.para || []).filter(Boolean).join(',');
// Sin nadie a quien escribirle no se manda nada. Intentarlo revienta el
// flujo y dispara la alerta de averia por lo que es un dato incompleto.
if (!para) return [];
return [{ json: { asunto, cuerpo, para } }];
